def leer_archivo(ruta):
    try:
        with open(ruta, "r") as f:
            return f.read()
    except FileNotFoundError:
        return f"Error: el archivo {ruta} no existe"
    except PermissionError:
        return f"Error: sin permisos para leer {ruta}"
    except IsADirectoryError:
        return f"Error: {ruta} es una carpeta, no un archivo"
    except UnicodeDecodeError:
        return f"Error: {ruta} no es un archivo de texto válido"

print(leer_archivo("no_existe.txt"))
print(leer_archivo("/"))

