import os

def guardar_seguro(ruta, contenido):
    # Verificar si la carpeta existe
    carpeta = os.path.dirname(ruta)
    if carpeta and not os.path.exists(carpeta):
        print(f"Creando carpeta {carpeta}...")
        try:
            os.makedirs(carpeta)
        except OSError as e:
            print(f"No se pudo crear la carpeta: {e}")
            return False

    # Verificar si el archivo existe
    if os.path.exists(ruta):
        print(f"Aviso: {ruta} ya existe. Se sobreescribirá.")

    try:
        with open(ruta, "w") as f:
            f.write(contenido)
        return True
    except PermissionError:
        print(f"Sin permisos para escribir en {ruta}")
        return False
    except OSError as e:
        print(f"Error al escribir: {e}")
        return False

guardar_seguro("datos/salida.txt", "Hola")
